var r=`1146-brownies`;var i=`world-1146`;var a=`US`;var o=`northern-america`;var n=8;var s=78;var u={en:`Brownies`,ua:`Брауні`};var d={en:`Brownies is a dish from United States prepared with chicken egg, all-purpose flour. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Брауні, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: куряче яйце, пшеничне борошно універсальне. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:8,i:[[`unsalted-butter`,185,`g`],[`white-granulated-sugar`,240,`g`],[`chicken-egg`,3,`pcs`]]},{en:`Melt the dark chocolate gently and cool slightly before folding it with flour and cocoa into the creamed egg-butter mixture; do not overmix.`,ua:`Обережно розтопіть темний шоколад і злегка остудіть, тоді змішайте з борошном та какао у збиту яєчно-масляну масу, не перемішуючи надмірно.`,t:[`folding-batter`],m:7,i:[[`dark-chocolate`,280,`g`],[`all-purpose-flour`,135,`g`],[`cocoa-powder`,55,`g`],[`table-salt`,3,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 28 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 28 хвилин до готовності.`,t:[`baking`],m:28,i:[]},{en:`Refrigerate the prepared mixture for about 35 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 35 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:35,i:[]}];var g={slug:r,id:i,country:`US`,region:o,servings:8,minutes:78,title:u,text:d,steps:l};export{a as country,g as default,i as id,s as minutes,o as region,n as servings,r as slug,l as steps,d as text,u as title};